import React, { useEffect, useRef, useState } from 'react';
import { Crosshair, Target, Navigation, Battery, Signal, Wind, Thermometer, Eye, Camera, AlertTriangle, MapPin, Locate, Maximize, Disc, Wifi } from 'lucide-react';

export const DroneApp: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);

    const [viewMode, setViewMode] = useState<'EO' | 'IR' | 'NV' | 'STREET'>('STREET'); 
    const [isScanning, setIsScanning] = useState(false);
    const [cameraAccess, setCameraAccess] = useState<boolean | null>(null);
    const [connectionStability, setConnectionStability] = useState(100);

    const streetImageRef = useRef<HTMLImageElement | null>(null);

    // Flight State
    const state = useRef({
        x: 0,
        y: 0,
        z: 150, // Altitude (Lower default for street view impact)
        vx: 0,
        vy: 0,
        heading: 0,
        pitch: 0,
        roll: 0,
        battery: 98,
        targets: [] as {x: number, y: number, type: string, id: string, speed: number, heading: number}[]
    });

    // Generate random targets on mount
    useEffect(() => {
        for(let i=0; i<20; i++) { // Increased target count
            state.current.targets.push({
                x: (Math.random() - 0.5) * 4000,
                y: (Math.random() - 0.5) * 4000,
                type: Math.random() > 0.5 ? 'VEHICLE' : 'PERSON',
                id: Math.random().toString(36).substring(2, 7).toUpperCase(),
                speed: Math.random() * 4, // Faster targets
                heading: Math.random() * 360
            });
        }

        // Load Street View Panorama simulation
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = "https://images.unsplash.com/photo-1542259681-d2622966430e?q=80&w=2500&auto=format&fit=crop"; // Tokyo Night Street
        img.onload = () => {
            streetImageRef.current = img;
        };

        // Connection stability simulation
        const interval = setInterval(() => {
            setConnectionStability(prev => Math.max(40, Math.min(100, prev + (Math.random() - 0.5) * 10)));
        }, 1000);

        return () => clearInterval(interval);
    }, []);

    // Camera Initialization
    useEffect(() => {
        const startCamera = async () => {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    video: { 
                        width: { ideal: 1280 }, 
                        height: { ideal: 720 },
                        facingMode: "environment"
                    } 
                });
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                    videoRef.current.onloadedmetadata = () => {
                        videoRef.current?.play().catch(e => console.error("Play error:", e));
                        setCameraAccess(true);
                    };
                }
            } catch (err) {
                setCameraAccess(false);
            }
        };
        startCamera();

        return () => {
            if (videoRef.current && videoRef.current.srcObject) {
                const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
                tracks.forEach(t => t.stop());
            }
        };
    }, []);

    // Input & Physics handling
    useEffect(() => {
        const keys = { w: false, a: false, s: false, d: false, ArrowUp: false, ArrowDown: false, Shift: false };

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Shift") keys.Shift = true;
            if ((keys as any)[e.key] !== undefined) (keys as any)[e.key] = true;
        };

        const handleKeyUp = (e: KeyboardEvent) => {
             if (e.key === "Shift") keys.Shift = false;
            if ((keys as any)[e.key] !== undefined) (keys as any)[e.key] = false;
        };

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);

        const loop = () => {
            const s = state.current;
            const speedMult = keys.Shift ? 2.0 : 0.5;

            // Move relative to heading
            const rad = (s.heading - 90) * Math.PI / 180; // Heading 0 is North (-Y), so rotate 90 to match Math 0 (East)

            let forward = 0;
            let strafe = 0;

            if (keys.w) forward += 1;
            if (keys.s) forward -= 1;
            if (keys.a) strafe -= 1;
            if (keys.d) strafe += 1;

            // Calculate global force vector
            // Heading 0 (North) -> cos(rad) = 0, sin(rad) = -1. 
            // W pressed (forward=1). vx += 0, vy += -1. Correct.
            s.vx += (Math.cos(rad) * forward - Math.sin(rad) * strafe) * speedMult;
            s.vy += (Math.sin(rad) * forward + Math.cos(rad) * strafe) * speedMult;

            // Altitude
            if (keys.ArrowUp) s.z = Math.min(2000, s.z + 2);
            if (keys.ArrowDown) s.z = Math.max(50, s.z - 2);

            // Drag
            s.vx *= 0.92;
            s.vy *= 0.92;

            // Position
            s.x += s.vx;
            s.y += s.vy;

            // Roll/Pitch based on movement relative to heading
            // Pitch depends on forward velocity
            // Roll depends on angular velocity or strafe (simplified here to strafe)

            // Project velocity onto heading vector
            const speed = Math.sqrt(s.vx*s.vx + s.vy*s.vy);
            const moveAngle = Math.atan2(s.vy, s.vx);
            const headingRad = (s.heading - 90) * Math.PI / 180;
            const relAngle = moveAngle - headingRad;

            const forwardSpeed = speed * Math.cos(relAngle);
            const strafeSpeed = speed * Math.sin(relAngle);

            s.pitch = forwardSpeed * -1.5; // Tilt down when moving forward
            s.roll = strafeSpeed * -2.0;   // Tilt based on strafe

            // Heading control (Mouse or Q/E would be better, but sticking to auto-pan or A/D override if needed)
            // Let's add Q/E for yaw if we wanted, but for now stick to simple drifting or existing controls
            if (viewMode === 'STREET') {
                 // Auto-pan drift
                 s.heading += 0.05;
            }

            // Update Targets
            s.targets.forEach(t => {
                 t.x += Math.cos(t.heading * Math.PI / 180) * t.speed;
                 t.y += Math.sin(t.heading * Math.PI / 180) * t.speed;
                 // Randomly change heading
                 if(Math.random() < 0.01) t.heading += (Math.random() - 0.5) * 90;
            });

            requestAnimationFrame(loop);
        };
        const animId = requestAnimationFrame(loop);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
            cancelAnimationFrame(animId);
        };
    }, [viewMode]);

    // Rendering Loop
    useEffect(() => {
        let animId: number;
        let frameCount = 0;

        const draw = () => {
            if (!canvasRef.current || !containerRef.current) return;
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) return;

            frameCount++;
            const width = canvasRef.current.width;
            const height = canvasRef.current.height;
            const s = state.current;

            // Colors based on mode
            let gridColor = 'rgba(0, 51, 51, 0.5)';
            let objectColor = '#00ffff';
            let hudColor = '#00f3ff';
            let fallbackBg = '#000000';

            if (viewMode === 'IR') { // White hot / Red HUD
                gridColor = 'rgba(100, 100, 100, 0.3)';
                objectColor = '#ffffff'; 
                hudColor = '#ff3333';
                fallbackBg = '#111111';
            } else if (viewMode === 'NV') { // Green Phosphor
                gridColor = 'rgba(0, 50, 0, 0.5)';
                objectColor = '#aaffaa';
                hudColor = '#00ff00';
                fallbackBg = '#001a00';
            } else if (viewMode === 'STREET') {
                hudColor = 'rgba(255, 255, 255, 0.9)';
                objectColor = '#00f3ff';
            }

            // --- 1. DRAW BACKGROUND LAYER ---

            if (viewMode === 'STREET' && streetImageRef.current) {
                const img = streetImageRef.current;
                const scale = (height / img.height) * 1.2; // Slight zoom to fill vertically
                const scaledWidth = img.width * scale;

                // Determine Panorama Offset based on Heading
                // Heading 0-360 maps to 0-scaledWidth
                const normalizedHeading = ((s.heading % 360) + 360) % 360;
                const xOffset = (normalizedHeading / 360) * scaledWidth;

                // Add jitter based on "flight" vibration
                const jitterX = (Math.random() - 0.5) * (speed(s) * 2);
                const jitterY = (Math.random() - 0.5) * (speed(s) * 2);

                const renderY = (height - (img.height * scale)) / 2 + s.pitch * 5 + jitterY; // Vertical shift based on pitch

                ctx.drawImage(img, -xOffset + jitterX, renderY, scaledWidth, img.height * scale);
                ctx.drawImage(img, -xOffset + scaledWidth + jitterX, renderY, scaledWidth, img.height * scale);
                ctx.drawImage(img, -xOffset - scaledWidth + jitterX, renderY, scaledWidth, img.height * scale);

            } else if (cameraAccess && videoRef.current && videoRef.current.readyState >= 2) {
                ctx.save();
                // Apply Filters
                if (viewMode === 'IR') {
                    ctx.filter = 'grayscale(100%) contrast(1.5) brightness(1.1) invert(1)';
                } else if (viewMode === 'NV') {
                    ctx.filter = 'sepia(100%) hue-rotate(50deg) saturate(400%) contrast(1.2) brightness(1.2)';
                } else {
                    ctx.filter = 'saturate(0.8) contrast(1.1)';
                }
                ctx.drawImage(videoRef.current, 0, 0, width, height);
                ctx.restore();
            } else {
                ctx.fillStyle = fallbackBg;
                ctx.fillRect(0, 0, width, height);
            }

            // --- 2. WORLD OBJECTS & TARGETS ---

            ctx.save();

            if (viewMode === 'STREET') {
                // Street View: Perspective Projection based on Bearing
                // FOV roughly 60-90 degrees for standard cam
                const FOV = 80;
                const pixelsPerDeg = width / FOV;
                const horizonY = height / 2 + s.pitch * 5; // Match bg shift

                s.targets.forEach(target => {
                    const dx = target.x - s.x;
                    const dy = target.y - s.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    if (dist > 1500) return; // Too far to see

                    // Calculate Bearing
                    // Math Angle: 0 = East (+X), 90 = South (+Y)
                    const mathAngle = Math.atan2(dy, dx); 
                    // Convert to Compass: 0 = North (-Y)
                    // -PI/2 in math = North.
                    let bearing = (mathAngle * 180 / Math.PI) + 90;

                    let relBearing = bearing - s.heading;
                    while (relBearing < -180) relBearing += 360;
                    while (relBearing > 180) relBearing -= 360;

                    // Visibility check
                    if (Math.abs(relBearing) < FOV / 1.5) {
                        const screenX = width / 2 + relBearing * pixelsPerDeg;

                        // Vertical Position
                        // Angle down = atan(altitude / dist)
                        const angleDown = Math.atan2(s.z, dist) * 180 / Math.PI;
                        const screenY = horizonY + angleDown * (pixelsPerDeg * 0.8);

                        // Scale size by distance
                        const baseSize = 50;
                        const scale = 300 / Math.max(50, dist); 
                        const size = baseSize * scale;

                        // Draw Bracket
                        if (size > 5) {
                            ctx.strokeStyle = objectColor;
                            ctx.lineWidth = 2;
                            drawBracket(ctx, screenX, screenY, size, size);

                            // Label
                            ctx.fillStyle = objectColor;
                            ctx.font = '10px monospace';
                            ctx.fillText(`${target.type.substring(0,3)}-${target.id}`, screenX + size/2 + 4, screenY - size/2);
                            ctx.fillStyle = 'rgba(255,255,255,0.7)';
                            ctx.fillText(`${Math.floor(dist)}m`, screenX + size/2 + 4, screenY - size/2 + 12);
                        }
                    }
                });

            } else {
                // Top-Down Orthographic (EO/IR/NV)
                ctx.translate(width/2, height/2);
                ctx.rotate(-s.roll * Math.PI / 180);
                ctx.translate(-width/2, -height/2);

                // Grid (Terrain)
                const gridSize = 100 * (500 / s.z); 
                const offsetX = s.x % gridSize;
                const offsetY = s.y % gridSize;
                ctx.strokeStyle = gridColor;
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let x = -gridSize; x < width + gridSize; x += gridSize) {
                    ctx.moveTo(x - offsetX, 0); ctx.lineTo(x - offsetX, height);
                }
                for (let y = -gridSize; y < height + gridSize; y += gridSize) {
                    ctx.moveTo(0, y - offsetY); ctx.lineTo(width, y - offsetY);
                }
                ctx.stroke();

                // Targets
                s.targets.forEach(target => {
                    const zoomFactor = 500 / s.z;
                    const relX = (target.x - s.x) * zoomFactor + width/2;
                    const relY = (target.y - s.y) * zoomFactor + height/2;

                    if (relX > -50 && relX < width + 50 && relY > -50 && relY < height + 50) {
                        const size = 40 * zoomFactor;
                        drawBracket(ctx, relX, relY, size, size, objectColor);
                        if (viewMode !== 'IR') {
                            ctx.fillStyle = objectColor;
                            ctx.font = '10px monospace';
                            ctx.fillText(`${target.type.substring(0,3)}`, relX + size/2 + 4, relY - size/2 + 10);
                        }
                    }
                });
            }
            ctx.restore();

            // --- 3. DIGITAL INTERFERENCE & SCANLINES ---

            // Scanlines
            ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
            for(let y = 0; y < height; y += 3) {
                ctx.fillRect(0, y, width, 1);
            }

            // Random Glitch Line
            if (Math.random() < 0.05 + (100 - connectionStability)/500) {
                const y = Math.random() * height;
                const h = Math.random() * 20 + 2;
                const shift = (Math.random() - 0.5) * 20;
                ctx.save();
                ctx.beginPath();
                ctx.rect(0, y, width, h);
                ctx.clip();
                ctx.drawImage(canvasRef.current, shift, 0);
                ctx.fillStyle = `rgba(${viewMode === 'IR' ? '255,255,255' : '0,243,255'}, 0.2)`;
                ctx.fillRect(0, y, width, h);
                ctx.restore();
            }

            // Vignette
            const grad = ctx.createRadialGradient(width/2, height/2, height/2, width/2, height/2, height);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(1, 'rgba(0,0,0,0.8)');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, width, height);


            // --- 4. HUD ---

            // Top Compass Tape
            drawCompass(ctx, width, s.heading, hudColor);

            // Center Reticle
            const cx = width/2;
            const cy = height/2;

            ctx.strokeStyle = isScanning ? '#ff0000' : hudColor;
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            const gap = isScanning ? 2 : 10;
            const len = 20;
            ctx.moveTo(cx - gap, cy); ctx.lineTo(cx - gap - len, cy);
            ctx.moveTo(cx + gap, cy); ctx.lineTo(cx + gap + len, cy);
            ctx.moveTo(cx, cy - gap); ctx.lineTo(cx, cy - gap - len);
            ctx.moveTo(cx, cy + gap); ctx.lineTo(cx, cy + gap + len);
            ctx.stroke();

            if (isScanning) {
                ctx.fillStyle = 'rgba(255, 0, 0, 0.2)';
                ctx.beginPath();
                ctx.arc(cx, cy, 100, 0, Math.PI*2);
                ctx.fill();
                ctx.beginPath();
                ctx.arc(cx, cy, 100, 0, Math.PI*2 * (frameCount % 60) / 60);
                ctx.strokeStyle = '#ff0000';
                ctx.stroke();
            }

            // Telemetry
            ctx.font = '12px monospace';
            ctx.fillStyle = hudColor;

            // Left Stack
            let ly = 100;
            const lx = 30;
            const lh = 20;

            ctx.textAlign = 'left';
            drawTelemetry(ctx, lx, ly, 'SPD', Math.floor(speed(s) * 30), 'KM/H'); ly+=lh;
            drawTelemetry(ctx, lx, ly, 'ALT', Math.floor(s.z), 'M'); ly+=lh;
            drawTelemetry(ctx, lx, ly, 'BAT', Math.floor(s.battery), '%'); ly+=lh;
            drawTelemetry(ctx, lx, ly, 'SIG', Math.floor(connectionStability), 'db'); ly+=lh;

            // Right Stack
            ly = 100;
            const rx = width - 30;
            ctx.textAlign = 'right';

            ctx.fillText(`LAT  35.6895° N`, rx, ly); ly+=lh;
            ctx.fillText(`LON  139.6917° E`, rx, ly); ly+=lh;
            ctx.fillText(`UTC  ${new Date().toISOString().substring(11, 19)}`, rx, ly); ly+=lh;
            ctx.fillText(`MODE ${viewMode}`, rx, ly); ly+=lh;

            // Artificial Horizon (Pitch Ladder)
            // Always show in street mode for realism
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(s.roll * Math.PI / 180);

            // Horizon Line
            const pitchPx = s.pitch * 5;
            ctx.strokeStyle = hudColor;
            ctx.beginPath();
            ctx.moveTo(-60, pitchPx); ctx.lineTo(60, pitchPx);
            ctx.stroke();

            // Ladder ticks
            ctx.fillStyle = hudColor;
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            for (let p = -20; p <= 20; p += 10) {
                if (p === 0) continue;
                const y = -p * 5 + pitchPx;
                if (y > -150 && y < 150) {
                     ctx.beginPath();
                     ctx.moveTo(-20, y); ctx.lineTo(20, y);
                     ctx.stroke();
                     ctx.fillText(p.toString(), -30, y+3);
                     ctx.fillText(p.toString(), 30, y+3);
                }
            }
            ctx.restore();

            // Recording Indicator
            if (frameCount % 60 < 30) {
                ctx.fillStyle = '#ff0000';
                ctx.beginPath();
                ctx.arc(40, 40, 6, 0, Math.PI*2);
                ctx.fill();
                ctx.font = 'bold 12px monospace';
                ctx.fillStyle = '#ff0000';
                ctx.textAlign = 'left';
                ctx.fillText('REC', 55, 44);
            }

            animId = requestAnimationFrame(draw);
        };
        draw();

        return () => cancelAnimationFrame(animId);
    }, [viewMode, isScanning, cameraAccess, connectionStability]);

    // Helpers
    const speed = (s: any) => Math.sqrt(s.vx*s.vx + s.vy*s.vy);

    const drawBracket = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color?: string) => {
        const halfW = w / 2;
        const halfH = h / 2;
        const c = w / 4; // corner length

        ctx.beginPath();
        // Top Left
        ctx.moveTo(x - halfW, y - halfH + c); ctx.lineTo(x - halfW, y - halfH); ctx.lineTo(x - halfW + c, y - halfH);
        // Top Right
        ctx.moveTo(x + halfW - c, y - halfH); ctx.lineTo(x + halfW, y - halfH); ctx.lineTo(x + halfW, y - halfH + c);
        // Bottom Right
        ctx.moveTo(x + halfW, y + halfH - c); ctx.lineTo(x + halfW, y + halfH); ctx.lineTo(x + halfW - c, y + halfH);
        // Bottom Left
        ctx.moveTo(x - halfW + c, y + halfH); ctx.lineTo(x - halfW, y + halfH); ctx.lineTo(x - halfW, y + halfH - c);
        ctx.stroke();
    };

    const drawTelemetry = (ctx: CanvasRenderingContext2D, x: number, y: number, label: string, val: any, unit: string) => {
        ctx.fillStyle = 'rgba(0, 243, 255, 0.6)';
        ctx.fillText(label, x, y);
        ctx.fillStyle = '#00f3ff';
        ctx.fillText(`${val} ${unit}`, x + 35, y);
    };

    const drawCompass = (ctx: CanvasRenderingContext2D, width: number, heading: number, color: string) => {
        const cw = 300;
        const cx = width / 2;
        const cy = 40;

        ctx.save();
        ctx.beginPath();
        ctx.rect(cx - cw/2, 0, cw, 60);
        ctx.clip();

        // Background
        const grad = ctx.createLinearGradient(cx - cw/2, 0, cx + cw/2, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.2, 'rgba(0,0,0,0.5)');
        grad.addColorStop(0.8, 'rgba(0,0,0,0.5)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(cx - cw/2, 20, cw, 30);

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.textAlign = 'center';
        ctx.font = '12px monospace';

        const pixelsPerDeg = 2.0;
        const startDeg = heading - (cw / 2 / pixelsPerDeg);
        const endDeg = heading + (cw / 2 / pixelsPerDeg);

        for (let d = Math.floor(startDeg / 10) * 10; d <= endDeg; d += 10) {
            const x = cx + (d - heading) * pixelsPerDeg;
            const normD = ((d % 360) + 360) % 360;

            let label = normD.toString();
            if (normD === 0) label = 'N';
            if (normD === 90) label = 'E';
            if (normD === 180) label = 'S';
            if (normD === 270) label = 'W';

            const isCard = ['N','E','S','W'].includes(label);
            const h = isCard ? 10 : 5;

            ctx.beginPath();
            ctx.moveTo(x, 50); ctx.lineTo(x, 50 - h);
            ctx.stroke();

            if (isCard || normD % 30 === 0) {
                ctx.fillText(label, x, 35);
            }
        }

        // Center Triangle
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.moveTo(cx, 55); ctx.lineTo(cx - 5, 60); ctx.lineTo(cx + 5, 60);
        ctx.fill();

        ctx.restore();
    };

    // Resize Handler
    useEffect(() => {
        const resize = () => {
            if (containerRef.current && canvasRef.current) {
                canvasRef.current.width = containerRef.current.clientWidth;
                canvasRef.current.height = containerRef.current.clientHeight;
            }
        };
        window.addEventListener('resize', resize);
        resize();
        return () => window.removeEventListener('resize', resize);
    }, []);

    return (
        <div className="h-full w-full bg-black flex flex-col relative" ref={containerRef}>
            {/* Hidden Video Element for Stream */}
            <video ref={videoRef} className="hidden" playsInline muted />

            <canvas ref={canvasRef} className="absolute inset-0 block z-0" />

            {/* UI Overlay Elements (React) */}
            <div className="absolute top-4 left-4 flex flex-col gap-2 z-10 pointer-events-none">
                 {/* Top Left info handled by canvas now for retro feel */}
            </div>

            {/* Controls */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-4 z-20">
                 {/* Mode Switcher */}
                 <div className="flex bg-black/80 border border-holo-border/30 rounded-full p-1 backdrop-blur-sm">
                     {['EO', 'IR', 'NV', 'STREET'].map((mode) => (
                         <button 
                            key={mode}
                            onClick={() => setViewMode(mode as any)}
                            className={`px-4 py-1.5 rounded-full text-[10px] font-bold font-mono transition-all ${viewMode === mode ? 'bg-holo-accent text-black shadow-glow' : 'text-holo-text/70 hover:text-white hover:bg-white/10'}`}
                         >
                             {mode === 'STREET' ? 'LIVE FEED' : mode}
                         </button>
                     ))}
                 </div>
            </div>

            <div className="absolute bottom-6 right-6 z-20">
                 <button 
                    className={`w-14 h-14 rounded-full border flex items-center justify-center transition-all ${isScanning ? 'border-red-500 bg-red-500/20 text-red-500 animate-pulse' : 'border-holo-accent bg-holo-accent/10 text-holo-accent hover:bg-holo-accent hover:text-black'}`}
                    onMouseDown={() => setIsScanning(true)}
                    onMouseUp={() => setIsScanning(false)}
                    onMouseLeave={() => setIsScanning(false)}
                 >
                     <Crosshair size={24} />
                 </button>
            </div>

            {/* Connection Status Icon Overlay */}
            <div className="absolute top-4 right-4 flex gap-2 z-10 pointer-events-none">
                <div className={`flex items-center gap-1 text-[10px] font-mono font-bold ${connectionStability > 70 ? 'text-holo-success' : 'text-holo-alert animate-pulse'}`}>
                    <Wifi size={14} />
                    {connectionStability > 80 ? 'STRONG' : 'UNSTABLE'}
                </div>
            </div>

            {/* Decorative Corners */}
            <div className="absolute top-4 left-4 w-12 h-12 border-t-2 border-l-2 border-white/30 pointer-events-none" />
            <div className="absolute top-4 right-4 w-12 h-12 border-t-2 border-r-2 border-white/30 pointer-events-none" />
            <div className="absolute bottom-4 left-4 w-12 h-12 border-b-2 border-l-2 border-white/30 pointer-events-none" />
            <div className="absolute bottom-4 right-4 w-12 h-12 border-b-2 border-r-2 border-white/30 pointer-events-none" />
        </div>
    );
};

